import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

/**
 * The contract's two hard rules for `src/game/`: no clock, no `Math.random`.
 * A comment may name them (this file's own subject matter does), so comments
 * are stripped before the code is searched.
 */
const SRC = join(process.cwd(), 'src/game');

const stripComments = (code: string): string =>
  code.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');

const sources = readdirSync(SRC)
  .filter((name) => name.endsWith('.ts'))
  .map((name) => ({ name, code: stripComments(readFileSync(join(SRC, name), 'utf8')) }));

const FORBIDDEN = [
  /\bMath\s*\.\s*random\b/,
  /\bDate\s*\.\s*now\b/,
  /\bperformance\s*\.\s*now\b/,
  /\bnew\s+Date\b/,
  /\bsetTimeout\b/,
  /\bsetInterval\b/,
  /\brequestAnimationFrame\b/,
  /\bdocument\b/,
  /\bwindow\b/,
];

describe('src/game is clock-free and random-free', () => {
  it('has sources to check', () => {
    expect(sources.map((s) => s.name).sort()).toEqual([
      'index.ts',
      'piece.ts',
      'queue.ts',
      'rng.ts',
      'state.ts',
      'step.ts',
    ]);
  });

  for (const { name, code } of sources) {
    it(`${name} reads no clock and no global randomness`, () => {
      const hits = FORBIDDEN.filter((pattern) => pattern.test(code)).map(String);
      expect(hits).toEqual([]);
    });
  }
});
